window.EP = {"name": "ch13", "label": "एपिसोड 13", "en": "The Tigress Nobody Could Stop", "duration": 1377.24, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 14.52, "text": "चैप्टर थर्टीन। द टाइग्रेस नोबडी कुड स्टॉप"}, {"start": 15.07, "end": 17.92, "text": "डे थर्टीन। चंपावत"}], "captions": [{"start": 19.47, "end": 22.9, "text": "कमांडेंट धामी ने रात एक बजकर दस मिनट पर फ़ोन किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 22.9, "end": 27.08, "text": "वो आवाज़ ऊँची करने वाले आदमी नहीं थे, तो जब उन्होंने ऊँची की,", "who": "", "voice": "narrator", "diary": false}, {"start": 27.08, "end": 29.47, "text": "मैंने फ़ोन अपने कान से दूर कर लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 29.92, "end": 30.78, "text": "आधी रात को?", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 30.78, "end": 31.25, "text": "अकेले?", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 31.25, "end": 33.99, "text": "एक गुंडे के साथ एक भुतहा बंगले में?", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 34.44, "end": 37.55, "text": "कमांडेंट साहब, टेक्निकली हम अकेले नहीं थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 37.55, "end": 38.51, "text": "आठ गायें थीं…", "who": "", "voice": "narrator", "diary": false}, {"start": 38.96, "end": 41.14, "text": "उन्हें ये मज़ेदार नहीं लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 41.14, "end": 46.74, "text": "उन्होंने मुझे बताया, कि ठीक-ठीक क्या करना है, छोटे, साफ़ वाक्यों में,", "who": "", "voice": "narrator", "diary": false}, {"start": 46.74, "end": 49.01, "text": "उसी तरह, जैसे मैं सोचता हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 49.01, "end": 52.65, "text": "वो कभी सरहद पर जवान सिपाहियों को बताते होंगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 53.1, "end": 56.75, "text": "अँधेरे में पहाड़ी सड़क पर रोहन का पीछा मत करो।", "who": "", "voice": "narrator", "diary": false}, {"start": 56.75, "end": 60.96, "text": "रोहन भी सुबह से पहले ऊँचे बुग्यालों तक नहीं पहुँचेगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 60.96, "end": 64.45, "text": "धामी के अपने लोग भोर तक मुनस्यारी में होंगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 64.45, "end": 68.42, "text": "लेकिन अगर हम चार वॉन्टेड चोरों की तरह वहाँ पहुँचे,", "who": "", "voice": "narrator", "diary": false}, {"start": 68.42, "end": 71.59, "text": "तो लोकल पुलिस पहले हमें गिरफ़्तार करेगी,", "who": "", "voice": "narrator", "diary": false}, {"start": 71.59, "end": 73.58, "text": "और सवाल दोपहर में पूछेगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 73.58, "end": 74.45, "text": "तो: चंपावत।", "who": "", "voice": "narrator", "diary": false}, {"start": 74.45, "end": 74.77, "text": "अभी।", "who": "", "voice": "narrator", "diary": false}, {"start": 74.77, "end": 78.5, "text": "उन्होंने किसी सीनियर के साथ एक मीटिंग तय की थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 78.5, "end": 81.12, "text": "जो कुछ भी तुम्हारे पास है, ले आओ।", "who": "", "voice": "narrator", "diary": false}, {"start": 81.12, "end": 81.83, "text": "हर फ़ोटो।", "who": "", "voice": "narrator", "diary": false}, {"start": 81.83, "end": 82.62, "text": "हर फ़्रेम।", "who": "", "voice": "narrator", "diary": false}, {"start": 82.62, "end": 83.26, "text": "हर शब्द।", "who": "", "voice": "narrator", "diary": false}, {"start": 83.71, "end": 85.04, "text": "और वो यूट्यूबर।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 85.24, "end": 86.0, "text": "उन्होंने जोड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 86.2, "end": 87.0, "text": "उसको भी लाओ।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 87.0, "end": 89.58, "text": "उसके पास सबसे ज़्यादा है, मुझे लगता है।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 90.03, "end": 96.11, "text": "मैंने अँधेरी पार्किंग के पार गोलू को देखा, जो अपनी सफ़ेद एस-यू-वी के बंपर पर अकेला बैठा,", "who": "", "voice": "narrator", "diary": false}, {"start": 96.11, "end": 99.36, "text": "अपने फ़ोन पर जी-पी-एस वाले बिंदु को देख रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 99.36, "end": 103.23, "text": "जो पहाड़ियों के बीच धीरे-धीरे उत्तर की तरफ़ रेंग रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 103.68, "end": 104.7, "text": "कमांडेंट साहब।", "who": "", "voice": "narrator", "diary": false}, {"start": 104.9, "end": 105.68, "text": "मैंने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 105.88, "end": 107.16, "text": "मुझे भी ऐसा ही लगता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 108.66, "end": 111.41, "text": "चंपावत, लोहाघाट से चौदह किलोमीटर दूर है,", "who": "", "voice": "narrator", "diary": false}, {"start": 111.41, "end": 114.29, "text": "अँधेरे में, चीड़ के जंगल से होते हुए नीचे।", "who": "", "voice": "narrator", "diary": false}, {"start": 114.29, "end": 118.75, "text": "रास्ते में, क्योंकि रात दो बजे की सड़क को एक कहानी चाहिए होती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 118.75, "end": 121.36, "text": "गब्बर ने हमें बाघिन के बारे में बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 121.81, "end": 124.61, "text": "कुमाऊँ के इस हिस्से का एक इतिहास है,", "who": "", "voice": "narrator", "diary": false}, {"start": 124.61, "end": 127.81, "text": "उन्होंने कहा, जिस पर ये मज़ाक़ नहीं करता।", "who": "", "voice": "narrator", "diary": false}, {"start": 127.81, "end": 131.62, "text": "उन्नीस सौ के शुरुआती सालों में, एक आदमख़ोर बाघिन,", "who": "", "voice": "narrator", "diary": false}, {"start": 131.62, "end": 134.27, "text": "सरहद पार करके इन पहाड़ियों में आई,", "who": "", "voice": "narrator", "diary": false}, {"start": 134.27, "end": 136.85, "text": "और सालों तक कोई उसे रोक नहीं सका।", "who": "", "voice": "narrator", "diary": false}, {"start": 136.85, "end": 138.64, "text": "वो जंगलों में मारती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 138.64, "end": 140.12, "text": "सड़कों पर मारती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 140.12, "end": 143.94, "text": "दिन-दहाड़े लोगों को उनके खेतों से उठा ले जाती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 143.94, "end": 148.92, "text": "उसने जितने लोग मारे, उनकी गिनती आमतौर पर सैकड़ों में की जाती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 148.92, "end": 151.57, "text": "गाँवों ने बाहर निकलना बंद कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 151.57, "end": 154.46, "text": "पूरी की पूरी घाटियाँ डर में जीती थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 154.91, "end": 158.44, "text": "उन्नीस सौ सात में, नैनीताल का एक जवान आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 158.44, "end": 161.15, "text": "जिम कॉर्बेट, उसका शिकार करने आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 161.15, "end": 166.41, "text": "उसने दिनों तक, इन्हीं पहाड़ियों में उसका पीछा किया, और आख़िरकार,", "who": "", "voice": "narrator", "diary": false}, {"start": 166.41, "end": 170.27, "text": "चंपावत के पास, पूरा क़स्बा उसके पीछे इकट्ठा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 170.27, "end": 172.08, "text": "जब उसने उसे गोली मारी।", "who": "", "voice": "narrator", "diary": false}, {"start": 172.08, "end": 178.33, "text": "सालों बाद, उसने इसके बारे में मैन-ईटर्स ऑफ़ कुमाऊँ नाम की एक किताब में लिखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 178.33, "end": 183.1, "text": "जो अब तक लिखी गई शिकार की सबसे मशहूर किताबों में से एक है।", "who": "", "voice": "narrator", "diary": false}, {"start": 183.55, "end": 185.55, "text": "मेरे परदादा ने भी उसे देखा था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 185.75, "end": 186.79, "text": "गब्बर ने मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 187.24, "end": 187.79, "text": "सच में?", "who": "", "voice": "narrator", "diary": false}, {"start": 188.24, "end": 189.01, "text": "लगभग।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 189.21, "end": 190.01, "text": "उन्होंने सोचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 190.21, "end": 193.16, "text": "एक बार उन्होंने उसकी दुम देखी थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 193.16, "end": 193.96, "text": "जंगल में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 193.96, "end": 194.85, "text": "इतनी लंबी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 195.05, "end": 197.48, "text": "उन्होंने स्टीयरिंग से एक हाथ हटाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 197.48, "end": 200.4, "text": "और अपने हाथ लगभग एक मीटर की दूरी पर फैलाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 200.85, "end": 204.04, "text": "पाँच मिनट बाद, एक अँधेरे मोड़ से गुज़रते हुए:", "who": "", "voice": "narrator", "diary": false}, {"start": 204.24, "end": 205.6, "text": "दुम इतनी लंबी थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 205.8, "end": 206.52, "text": "दो मीटर।", "who": "", "voice": "narrator", "diary": false}, {"start": 206.97, "end": 209.33, "text": "चंपावत के किनारे पर:", "who": "", "voice": "narrator", "diary": false}, {"start": 209.53, "end": 212.6, "text": "और आँखें, प्रोफ़ेसर साहब, बास्केटबॉल जितनी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 213.05, "end": 215.56, "text": "क्षितिज ने अपनी नई नोटबुक से नज़र नहीं उठाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 215.76, "end": 219.91, "text": "गब्बर भैया, आपकी कहानी में बाघिन हर किलोमीटर पे बड़ी हो रही है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 220.36, "end": 222.89, "text": "पहाड़ में कहानियाँ बढ़ती हैं, बेटा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 223.09, "end": 226.28, "text": "गब्बर ने बड़ी गरिमा के साथ उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 226.48, "end": 228.51, "text": "बची राम जी ने भी गीत बदला था ना?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 228.96, "end": 233.11, "text": "और चितई के बाद पहली बार, गब्बर सिंह नेगी हँसे।", "who": "", "voice": "narrator", "diary": false}, {"start": 233.56, "end": 237.39, "text": "हेडलाइट्स में हम एक साइनबोर्ड के पास से गुज़रे: देवीधुरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 237.39, "end": 238.59, "text": "पैंतालीस किलोमीटर।", "who": "", "voice": "narrator", "diary": false}, {"start": 238.59, "end": 240.6, "text": "गब्बर ने उसकी तरफ़ इशारा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 241.05, "end": 243.29, "text": "वहाँ राखी के दिन बग्वाल होती है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 243.49, "end": 244.6, "text": "उन्होंने हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 244.8, "end": 246.09, "text": "पत्थर की लड़ाई।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 246.09, "end": 248.23, "text": "बाराही देवी के मंदिर में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 248.23, "end": 252.43, "text": "चार खाम, चार कुनबे, एक-दूसरे पे पत्थर फेंकते हैं,", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 252.43, "end": 253.97, "text": "लकड़ी की ढाल लेके।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 253.97, "end": 259.12, "text": "कहते हैं, पहले देवी को हर साल एक इंसान की बलि चाहिए होती थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 259.12, "end": 262.89, "text": "एक साल, एक बुढ़िया के अकेले पोते की बारी आई।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 262.89, "end": 265.29, "text": "बुढ़िया ने देवी से विनती की।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 265.29, "end": 267.01, "text": "देवी ने कहा, ठीक है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 267.01, "end": 269.84, "text": "एक आदमी के ख़ून जितना ख़ून दे दो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 269.84, "end": 271.55, "text": "एक आदमी की जान नहीं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 271.55, "end": 273.35, "text": "तब से बग्वाल होती है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 273.35, "end": 276.53, "text": "अब तो फल भी फेंकते हैं, पत्थर के साथ।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 276.98, "end": 278.76, "text": "क्षितिज ने वो लिख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 278.76, "end": 282.79, "text": "फिर उसके नीचे, छोटे अक्षरों में, उसने लिखा: एक देवी,", "who": "", "voice": "narrator", "diary": false}, {"start": 282.79, "end": 286.44, "text": "जो जितना माँगा था, उससे कम लेने को राज़ी हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 286.89, "end": 289.55, "text": "मैंने उस वाक्य के बारे में देर तक सोचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 289.55, "end": 290.64, "text": "अब भी सोचता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 292.14, "end": 294.56, "text": "हम सुबह चार बजे चंपावत पहुँचे।", "who": "", "voice": "narrator", "diary": false}, {"start": 294.56, "end": 296.99, "text": "मीटिंग आठ बजे से पहले नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 296.99, "end": 301.02, "text": "धामी ने हमसे कहीं शांत जगह इंतज़ार करने को कहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 301.47, "end": 308.65, "text": "गोलू, बिना कुछ समझाए, हमें एक तंग गली से ऊपर, क़स्बे के किनारे, एक ऊँचाई पर बने एक छोटे,", "who": "", "voice": "narrator", "diary": false}, {"start": 308.65, "end": 313.95, "text": "पुराने मंदिर तक ले गया, जहाँ से पूरब में अँधेरी पहाड़ियों के पार,", "who": "", "voice": "narrator", "diary": false}, {"start": 313.95, "end": 315.9, "text": "नेपाल की तरफ़ नज़ारा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 315.9, "end": 317.78, "text": "गोलू देवता का एक मंदिर।", "who": "", "voice": "narrator", "diary": false}, {"start": 317.78, "end": 319.0, "text": "वही गोलू देवता।", "who": "", "voice": "narrator", "diary": false}, {"start": 319.0, "end": 324.95, "text": "आख़िर, चंपावत ही वो जगह है, जहाँ से उनकी कहानी शुरू होती है: राजा झल राय,", "who": "", "voice": "narrator", "diary": false}, {"start": 324.95, "end": 329.44, "text": "रानी कालिंका, पालने में पत्थर, लकड़ी के घोड़े पर लड़का।", "who": "", "voice": "narrator", "diary": false}, {"start": 329.89, "end": 332.34, "text": "हम ठंड में सीढ़ियों पर बैठ गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 332.34, "end": 336.09, "text": "आसमान अभी किनारों पर धूसर होना शुरू ही हुआ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 336.54, "end": 340.74, "text": "और गोलू ने, बिना किसी के पूछे, अपनी पफ़र जैकेट उतारी,", "who": "", "voice": "narrator", "diary": false}, {"start": 340.74, "end": 343.59, "text": "और उसे मोड़कर अपने बग़ल में रख दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 343.59, "end": 351.76, "text": "फिर उसने वो टोपी उतारी, जो वो हमेशा पहनता था, वो पुरानी नीली वाली, उसकी इकलौती चीज़, जो कभी नई नहीं थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 351.76, "end": 355.32, "text": "और उसे दोनों हाथों में अपनी गोद में थाम लिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 355.32, "end": 359.13, "text": "सामने लगे घिसे हुए बैज पर अपना अँगूठा फेरते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 359.13, "end": 362.22, "text": "फिर उसने दोनों हाथों से अपना चेहरा मला,", "who": "", "voice": "narrator", "diary": false}, {"start": 362.22, "end": 366.02, "text": "और जब उसने उन्हें नीचे किया, तो कुछ बदल चुका था।", "who": "", "voice": "narrator", "diary": false}, {"start": 366.02, "end": 367.29, "text": "उसका चेहरा नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 367.29, "end": 369.91, "text": "वो ढंग, जिससे वो उसे थामे हुए था।", "who": "", "voice": "narrator", "diary": false}, {"start": 370.36, "end": 372.41, "text": "मेरा नाम गौरव है।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 372.61, "end": 373.25, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 373.7, "end": 376.1, "text": "कोई यूट्यूब वाली आवाज़ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 376.1, "end": 378.34, "text": "कोई दिल्ली वाला लहजा नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 378.34, "end": 382.98, "text": "नरम, स्थिर, पहाड़ी हिंदी, जिसके किनारों पर गढ़वाली थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 382.98, "end": 387.45, "text": "उसने ये हम सबसे कहा, लेकिन वो क्षितिज को देख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 387.9, "end": 388.75, "text": "गौरव रावत।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 388.75, "end": 390.95, "text": "द्रोणागिरी के पास का गाँव।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 390.95, "end": 393.66, "text": "कमला दादी, मेरी दादी की बहन हैं।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 393.86, "end": 394.42, "text": "वो रुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 394.62, "end": 399.79, "text": "प्रताप सिंह रावत, तुम्हारे बही वाला नाम, मेरे दादा थे।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 400.49, "end": 401.99, "text": "किसी ने साँस नहीं ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 402.69, "end": 403.81, "text": "और दीपक।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 404.01, "end": 404.76, "text": "गौरव ने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 404.96, "end": 406.1, "text": "मेरा बड़ा भाई था।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 406.55, "end": 409.67, "text": "उसने इसे सीधे-सादे ढंग से बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 409.67, "end": 412.3, "text": "मैं भी इसे उसी तरह बताऊँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 412.75, "end": 415.69, "text": "दीपक रावत, गौरव से चार साल बड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 415.69, "end": 419.3, "text": "सत्रह साल की उम्र से हाई-एल्टीट्यूड पोर्टर।", "who": "", "voice": "narrator", "diary": false}, {"start": 419.3, "end": 423.33, "text": "मज़बूत, हँसमुख, बर्फ़ पर निडर: उस तरह का पोर्टर,", "who": "", "voice": "narrator", "diary": false}, {"start": 423.33, "end": 426.95, "text": "जिसे एक्सपीडिशन लीडर्स नाम लेकर माँगते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 426.95, "end": 430.64, "text": "उसे पुराने गीत बहुत पसंद थे, ख़ासकर वो वाला,", "who": "", "voice": "narrator", "diary": false}, {"start": 430.64, "end": 433.42, "text": "जो उनके दादा प्रताप गाया करते थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 433.42, "end": 436.36, "text": "बर्फ़ में एक गरम पत्थर के बारे में।", "who": "", "voice": "narrator", "diary": false}, {"start": 436.36, "end": 440.22, "text": "गौरव, छोटा भाई, हमेशा इस बात पर उसे छेड़ता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 440.22, "end": 442.24, "text": "पुराने गाने, पुराने लोग।", "who": "", "voice": "narrator", "diary": false}, {"start": 442.24, "end": 445.68, "text": "गौरव देहरादून में इंजीनियर बनना चाहता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 445.68, "end": 448.88, "text": "दीपक जानना चाहता था, कि पत्थर कहाँ है।", "who": "", "voice": "narrator", "diary": false}, {"start": 449.33, "end": 450.21, "text": "दो साल पहले,", "who": "", "voice": "narrator", "diary": false}, {"start": 450.21, "end": 455.08, "text": "समिट सीक्रेट्स ने दीपक को एक प्राइवेट एक्सपीडिशन के लिए हायर किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 455.08, "end": 456.48, "text": "पैसे बहुत अच्छे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 456.48, "end": 460.53, "text": "मंज़िल धुँधली थी: कहीं ऊँचे पर, बंद सैंक्चुअरी की तरफ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 460.53, "end": 462.97, "text": "रोहन सहगल ख़ुद उसे लीड कर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 463.42, "end": 466.06, "text": "दीपक अक्टूबर की शुरुआत में ऊपर गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 466.51, "end": 469.14, "text": "जाने से पहले देहरादून आया था, मेरे हॉस्टल।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 469.34, "end": 470.96, "text": "गौरव ने हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 470.96, "end": 474.61, "text": "उसने नीली टोपी को अपने हाथों में उलटा-पलटा।", "who": "", "voice": "narrator", "diary": false}, {"start": 474.81, "end": 475.54, "text": "ये दे गया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 475.54, "end": 481.33, "text": "उत्तरकाशी के माउंटेनियरिंग इंस्टिट्यूट का कैप है; वहाँ बेसिक कोर्स किया था उसने,", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 481.33, "end": 482.27, "text": "स्कॉलरशिप पे।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 482.27, "end": 485.52, "text": "बोला, तेरी इंजीनियरिंग की सर्दी में काम आएगी।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 485.52, "end": 486.18, "text": "मैं हँसा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 486.18, "end": 489.07, "text": "मैंने कहा, पहाड़ पे अकेले मत जाना, हीरो।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 489.07, "end": 489.87, "text": "मज़ाक़ में।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 489.87, "end": 493.99, "text": "वो बोला, अकेला कहाँ हूँ, सहगल साहब हैं, उनकी पूरी टीम है।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 494.69, "end": 495.41, "text": "वो रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 496.11, "end": 499.79, "text": "वो आख़िरी बात थी, जो मैंने उससे कही।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 499.79, "end": 500.91, "text": "आमने-सामने।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 501.36, "end": 503.45, "text": "पहाड़ पे अकेले मत जाना।", "who": "", "voice": "narrator", "diary": false}, {"start": 503.45, "end": 506.62, "text": "हर वीडियो के आख़िर वाला कैचफ़्रेज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 506.62, "end": 508.07, "text": "चार सौ वीडियोज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 508.07, "end": 510.16, "text": "पचास लाख सब्सक्राइबर्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 510.16, "end": 517.32, "text": "उनमें से हर एक, एक छोटे भाई के अपने बड़े भाई से कहे आख़िरी शब्द सुनता आ रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 517.32, "end": 520.95, "text": "एक आँख मारकर कहे हुए, और हँसता आ रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 521.65, "end": 523.0, "text": "दीपक नीचे नहीं आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 523.7, "end": 526.47, "text": "कंपनी ने कहा, कि ट्रिप के आख़िर में,", "who": "", "voice": "narrator", "diary": false}, {"start": 526.47, "end": 529.92, "text": "ख़राब मौसम में, वो एक क्रेवास में गिर गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 529.92, "end": 530.99, "text": "एक दुखद हादसा।", "who": "", "voice": "narrator", "diary": false}, {"start": 530.99, "end": 532.75, "text": "लाश नहीं निकाली जा सकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 532.75, "end": 538.27, "text": "वो एक बड़ी गाड़ी में गाँव आए, फूलों और एक चेक के साथ, और एक वकील के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 538.27, "end": 542.34, "text": "जिसने बड़े प्यार से समझाया, कि सबके लिए यही अच्छा है,", "who": "", "voice": "narrator", "diary": false}, {"start": 542.34, "end": 544.56, "text": "कि कोई परेशानी न खड़ी की जाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 544.56, "end": 545.79, "text": "परिवार ग़रीब था।", "who": "", "voice": "narrator", "diary": false}, {"start": 545.79, "end": 546.71, "text": "चेक बड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 546.71, "end": 549.62, "text": "और दुख, गौरव ने कहा, आपको थका देता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 550.07, "end": 552.86, "text": "पर दीपक ने एक आख़िरी वॉइस नोट भेजा था।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 553.06, "end": 554.16, "text": "उसने हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 554.36, "end": 556.71, "text": "किसी और के सैटेलाइट फ़ोन से।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 556.71, "end": 557.8, "text": "मेरे फ़ोन पे।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 557.8, "end": 559.31, "text": "मैं हॉस्टल में था।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 559.31, "end": 562.08, "text": "मैंने उसे सुनने में तीन दिन लगाए।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 562.53, "end": 564.38, "text": "उसने अपना फ़ोन निकाला।", "who": "", "voice": "narrator", "diary": false}, {"start": 564.38, "end": 566.57, "text": "उसके हाथ बिल्कुल स्थिर थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 566.57, "end": 570.01, "text": "मुझे लगता है, उसने उसे इतनी बार चलाया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 570.01, "end": 574.13, "text": "कि उसके हाथों ने बहुत पहले काँपना बंद कर दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 574.83, "end": 576.27, "text": "उसने प्ले दबाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 576.97, "end": 577.33, "text": "हवा।", "who": "", "voice": "narrator", "diary": false}, {"start": 577.33, "end": 578.62, "text": "बहुत सारी हवा।", "who": "", "voice": "narrator", "diary": false}, {"start": 578.62, "end": 579.81, "text": "एक खड़खड़ाहट।", "who": "", "voice": "narrator", "diary": false}, {"start": 579.81, "end": 585.51, "text": "और फिर एक जवान आदमी की आवाज़, हँसमुख, हाँफती हुई, और बहुत पास,", "who": "", "voice": "narrator", "diary": false}, {"start": 585.51, "end": 590.01, "text": "गढ़वाली में तेज़-तेज़ बोलती हुई, थोड़ा हँसते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 590.46, "end": 593.9, "text": "गौरव ने चलते-चलते, धीरे से, हमारे लिए उसका मतलब बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 594.35, "end": 594.68, "text": "गौरव।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 594.68, "end": 594.94, "text": "सुन।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 594.94, "end": 596.61, "text": "दादा वाला गीत सच है, यार।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 596.61, "end": 598.74, "text": "सहगल साहब गरम शिला ढूँढ रहे हैं।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 598.74, "end": 599.87, "text": "ये सर्वे नहीं है।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 599.87, "end": 603.79, "text": "उनके पास मशीन है, और एक डब्बा है, जिस पे ख़तरे का निशान है।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 603.79, "end": 605.85, "text": "मैं समझ गया, क्या ढूँढ रहे हैं।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 605.85, "end": 606.85, "text": "मैं मना करूँगा।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 606.85, "end": 608.45, "text": "मैं वापस आके सब बताऊँगा।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 608.45, "end": 609.91, "text": "मम्मी को मत बताना अभी।", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 609.91, "end": 611.31, "text": "दादा का गीत याद रखना…", "who": "दीपक", "voice": "deepak", "diary": false}, {"start": 611.76, "end": 613.19, "text": "हवा ने बाक़ी निगल लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 613.19, "end": 614.62, "text": "रिकॉर्डिंग ख़त्म हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 615.07, "end": 619.89, "text": "मंदिर की उन सीढ़ियों पर, बहुत देर तक, किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 620.34, "end": 621.69, "text": "नीचे क़स्बे में कहीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 621.69, "end": 624.65, "text": "सुबह की आरती के लिए एक मंदिर की घंटी बजने लगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 625.1, "end": 626.0, "text": "पुलिस के पास गया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 626.2, "end": 626.96, "text": "गौरव ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 627.16, "end": 627.73, "text": "दो बार।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 627.73, "end": 628.7, "text": "एक वॉइस नोट।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 628.7, "end": 629.93, "text": "एक पुराना गाना।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 629.93, "end": 631.72, "text": "एक अमीर आदमी की कंपनी।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 631.72, "end": 635.14, "text": "उन्होंने कहा, भाई की मौत का सदमा है, बेटा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 635.14, "end": 638.4, "text": "एक ने तो कहा, ये गीत-शीत का चक्कर छोड़ो।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 638.85, "end": 642.4, "text": "वो मुस्कुराया, एक छोटी, उदास मुस्कान।", "who": "", "voice": "narrator", "diary": false}, {"start": 642.85, "end": 643.98, "text": "तब मैंने सोचा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 643.98, "end": 646.96, "text": "कोई गाँव के लड़के की बात नहीं सुनेगा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 646.96, "end": 649.54, "text": "कोई इंजीनियर की बात नहीं सुनेगा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 649.54, "end": 651.47, "text": "पर एक बेवक़ूफ़ यूट्यूबर?", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 651.47, "end": 652.84, "text": "जो भूत ढूँढता है?", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 652.84, "end": 655.02, "text": "उसे कोई सीरियसली नहीं लेता।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 655.02, "end": 657.04, "text": "और वो कहीं भी जा सकता है।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 657.04, "end": 657.6, "text": "रात को।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 657.6, "end": 658.33, "text": "होटल में।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 658.33, "end": 659.05, "text": "जंगल में।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 659.05, "end": 661.23, "text": "किसी के भी पीछे कैमरा लेके।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 661.23, "end": 662.52, "text": "और सब हँसते हैं।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 662.97, "end": 664.46, "text": "घोस्टबस्टर गोलू।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 664.66, "end": 666.09, "text": "शाओनी ने धीरे से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 666.54, "end": 667.41, "text": "चौदह महीने।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 667.61, "end": 668.56, "text": "गौरव ने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 668.76, "end": 672.27, "text": "चौदह महीने से सहगल का पीछा कर रहा हूँ।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 672.27, "end": 673.01, "text": "हर होटल।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 673.01, "end": 674.12, "text": "हर ट्रेलहेड।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 674.12, "end": 674.86, "text": "हर कैंप।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 674.86, "end": 678.47, "text": "भूत के वीडियोज़ के पीछे, उसके वीडियोज़।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 678.67, "end": 679.79, "text": "वो मेरी तरफ़ मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 679.99, "end": 683.05, "text": "सवॉय में मैं उसके लिए आया था, प्रोफ़ेसर साहब।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 683.05, "end": 684.0, "text": "आपके लिए नहीं।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 684.0, "end": 684.88, "text": "ट्रैकर लगाने।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 684.88, "end": 687.73, "text": "फिर आप आ गए, सफ़ेद शॉल में, और सब बदल गया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 688.18, "end": 691.53, "text": "फिर उसने बाक़ी सब समझाया, टुकड़ा-दर-टुकड़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 691.53, "end": 694.48, "text": "और हर टुकड़ा एक ऐसे गड्ढे में जा गिरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 694.48, "end": 697.13, "text": "जिसके होने का मुझे पता ही नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 697.58, "end": 703.37, "text": "उसकी लाइव स्ट्रीम पर एन-डी-पैंसठ वाला कमेंट: रोहन के लोग गोलू का चैनल देखते थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 703.37, "end": 706.9, "text": "क्योंकि गोलू उनके कैंपों के आसपास दिखता रहता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 706.9, "end": 712.03, "text": "उन्होंने उसके ज़रिए हम तक एक मैसेज भेजने के लिए उसका इस्तेमाल किया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 712.03, "end": 716.22, "text": "और उसे ये जताने के लिए, कि उन्होंने उसे नोटिस कर लिया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 716.67, "end": 721.08, "text": "चोपता की लाल मिट्टी: वो पूरी रात, लाइटें बंद करके,", "who": "", "voice": "narrator", "diary": false}, {"start": 721.08, "end": 725.75, "text": "उस गाड़ी का पीछा करता रहा था, जो क्षितिज को ले गई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 725.75, "end": 727.96, "text": "धार पर वो उसे खो बैठा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 728.41, "end": 733.65, "text": "द्रोणागिरी: वो इसलिए भागा, क्योंकि कमला दादी ने उसका असली नाम ले लिया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 733.65, "end": 736.46, "text": "और अगर रोहन की टीम का कोई देख रहा होता,", "who": "", "voice": "narrator", "diary": false}, {"start": 736.46, "end": 740.34, "text": "तो चौदह महीनों में उसने जो कुछ बनाया था, सब बिखर जाता।", "who": "", "voice": "narrator", "diary": false}, {"start": 740.79, "end": 743.48, "text": "औली का ड्रोन: उसे हफ़्तों से पता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 743.48, "end": 745.95, "text": "कि रोहन का छुपा हुआ कैंप कहाँ है।", "who": "", "voice": "narrator", "diary": false}, {"start": 745.95, "end": 749.62, "text": "उसने जानबूझकर ड्रोन उसके ऊपर उड़ाया, ताकि कोई और,", "who": "", "voice": "narrator", "diary": false}, {"start": 749.62, "end": 753.21, "text": "कोई ऐसा, जिस पर लोग सच में यक़ीन करें, उसे देखे।", "who": "", "voice": "narrator", "diary": false}, {"start": 753.21, "end": 754.56, "text": "फिर वो इसलिए भागा,", "who": "", "voice": "narrator", "diary": false}, {"start": 754.56, "end": 758.15, "text": "क्योंकि रोहन के आदमियों ने भी ड्रोन देख लिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 758.85, "end": 759.87, "text": "और भल्ला।", "who": "", "voice": "narrator", "diary": false}, {"start": 760.57, "end": 761.29, "text": "वो भी था।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 761.49, "end": 762.25, "text": "गौरव ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 762.45, "end": 763.71, "text": "उस एक्सपीडिशन पे।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 763.71, "end": 764.6, "text": "दीपक के साथ।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 764.6, "end": 767.27, "text": "उसकी फ़ोटो है मेरे पास, बेस कैंप पे,", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 767.27, "end": 769.94, "text": "दोनों एक ही थर्मस से चाय पी रहे हैं।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 770.14, "end": 775.24, "text": "उसने स्क्रॉल किया, और फ़ोन हमारी तरफ़ बढ़ाया: एक जवान, दुबला भल्ला, हँसता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 775.24, "end": 777.72, "text": "उसकी बाँह एक हँसमुख लड़के के कंधों पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 777.72, "end": 780.85, "text": "जिसकी भौंहों पर पाला जमा था, और सिर पर कुछ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 781.05, "end": 783.9, "text": "वापस आया, तो किसी से बात नहीं की।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 783.9, "end": 786.32, "text": "कंपनी ने उसे प्रमोट कर दिया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 786.77, "end": 789.07, "text": "क्षितिज बिल्कुल स्थिर हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 789.07, "end": 793.84, "text": "मैंने उसे नई नोटबुक में पीछे जाते देखा, और फिर उससे भी पीछे,", "who": "", "voice": "narrator", "diary": false}, {"start": 793.84, "end": 797.96, "text": "अपनी याद में, उस पुरानी डायरी तक, जो रोहन ले गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 798.41, "end": 801.06, "text": "बड़े आदमी को बाँसुरी पसंद नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 801.06, "end": 801.91, "text": "गाना नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 801.91, "end": 802.77, "text": "यहाँ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 802.77, "end": 804.14, "text": "माफ़ कर दे, भाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 804.14, "end": 805.84, "text": "मैं कुछ नहीं कर सका।", "who": "", "voice": "narrator", "diary": false}, {"start": 806.29, "end": 807.84, "text": "वो दीपक से माफ़ी माँग रहा था।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 808.04, "end": 810.65, "text": "क्षितिज ने धीरे-धीरे, अपनी बहन से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 810.85, "end": 811.75, "text": "हर रात।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 811.75, "end": 813.16, "text": "अँधेरे में।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 813.16, "end": 815.2, "text": "इसलिए सोता नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 815.2, "end": 817.89, "text": "इसलिए गीत से डरता है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 818.09, "end": 819.28, "text": "वो गौरव की तरफ़ मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 819.48, "end": 820.69, "text": "दीपक गाता था ना?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 820.69, "end": 821.23, "text": "रात को?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 821.23, "end": 821.91, "text": "कैंप में?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 822.61, "end": 823.73, "text": "गौरव ने उसे घूरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 824.43, "end": 825.21, "text": "हर रात।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 825.41, "end": 826.05, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 826.25, "end": 827.43, "text": "दादा वाला गीत।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 827.43, "end": 829.12, "text": "सबको परेशान करता था।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 829.57, "end": 831.37, "text": "किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 831.37, "end": 834.28, "text": "हमारे नीचे, आरती की घंटी बजती रही।", "who": "", "voice": "narrator", "diary": false}, {"start": 834.98, "end": 836.47, "text": "और फिर, जागर।", "who": "", "voice": "narrator", "diary": false}, {"start": 837.17, "end": 841.94, "text": "जब देवता ने कहा, जो पहाड़ ने लिया है, उसे वापस मत माँगो…", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 842.14, "end": 843.16, "text": "गौरव रुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 843.16, "end": 845.0, "text": "उसका जबड़ा कस गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 845.2, "end": 848.14, "text": "मुझे लगा, वो मुझसे कह रहे हैं।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 848.14, "end": 850.59, "text": "कि दीपक को वापस मत माँगो।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 850.59, "end": 852.94, "text": "कि पहाड़ ने उसे ले लिया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 853.14, "end": 855.62, "text": "उसने उजली होती पहाड़ियों की तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 855.82, "end": 856.86, "text": "शायद ले लिया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 856.86, "end": 860.51, "text": "पर जिसने उसे वहाँ भेजा, उसे मैं नहीं छोड़ूँगा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 862.01, "end": 862.49, "text": "रीडर।", "who": "", "voice": "narrator", "diary": false}, {"start": 863.19, "end": 866.96, "text": "मुझे यहाँ एक पल के लिए कहानी रोकनी होगी,", "who": "", "voice": "narrator", "diary": false}, {"start": 866.96, "end": 870.36, "text": "क्योंकि मुझ पर किसी का कुछ बाक़ी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 870.81, "end": 874.19, "text": "बारह चैप्टर्स तक, मैंने इस आदमी का मज़ाक़ उड़ाया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 874.19, "end": 875.42, "text": "मैंने उसे जोकर कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 875.42, "end": 878.41, "text": "मैंने आपको उसकी रिंग लाइट, उसकी सूप वाली चीख़,", "who": "", "voice": "narrator", "diary": false}, {"start": 878.41, "end": 881.66, "text": "और उसके घोस्ट फ़ैमिली, क्या हाल है, पर हँसने दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 881.66, "end": 886.27, "text": "मैंने उसे अपनी किताब का कॉमिक रिलीफ़ बना दिया, क्योंकि वो यही चाहता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 886.27, "end": 889.51, "text": "कि सब देखें, और मैं ख़ुशी-ख़ुशी ठीक वही देखता रहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 889.51, "end": 890.75, "text": "जो मुझे दिखाया गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 891.2, "end": 894.32, "text": "वो इस ट्रिप का सबसे बहादुर इंसान था।", "who": "", "voice": "narrator", "diary": false}, {"start": 894.77, "end": 902.66, "text": "वो हम में से अकेला था, जिसे शुरू से पता था, कि दाँव पर क्या है, और उसने चौदह महीने तक इसे अकेले उठाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 902.66, "end": 907.38, "text": "एक ऐसे मुखौटे के पीछे, जो हर दिन अजनबियों को उस पर हँसाता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 907.38, "end": 912.25, "text": "उसने एक भुतहा होटल में एक अपराधी की गाड़ी के नीचे ट्रैकर लगाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 912.25, "end": 915.35, "text": "उसने पूरी रात बिना लाइटों के गाड़ी चलाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 915.35, "end": 918.29, "text": "वो एक जागर में एक ऐसे भाई के लिए रोया,", "who": "", "voice": "narrator", "diary": false}, {"start": 918.29, "end": 921.39, "text": "जिसे वो पहाड़ से वापस नहीं माँग सकता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 921.39, "end": 926.03, "text": "और जब हमने उसे चितई में दस हज़ार घंटियों के नीचे निकाल दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 926.03, "end": 927.34, "text": "उसने बहस नहीं की।", "who": "", "voice": "narrator", "diary": false}, {"start": 927.34, "end": 929.59, "text": "वो बस गाड़ी का पीछा करता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 930.04, "end": 932.6, "text": "मुझ पर गौरव रावत की एक माफ़ी बाक़ी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 933.05, "end": 934.92, "text": "और रीडर, आप पर भी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 934.92, "end": 936.17, "text": "आप भी हँसे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 936.17, "end": 937.6, "text": "मैंने आपको देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 938.05, "end": 940.61, "text": "मैं उसकी तरफ़ मुड़ा, सूर्योदय के वक़्त,", "who": "", "voice": "narrator", "diary": false}, {"start": 940.61, "end": 943.97, "text": "उसके देवता के मंदिर की सीढ़ियों पर, और ज़ोर से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 944.17, "end": 944.72, "text": "गौरव।", "who": "", "voice": "narrator", "diary": false}, {"start": 944.72, "end": 945.81, "text": "माफ़ करना।", "who": "", "voice": "narrator", "diary": false}, {"start": 945.81, "end": 947.13, "text": "मैं ग़लत था।", "who": "", "voice": "narrator", "diary": false}, {"start": 947.58, "end": 949.55, "text": "उसने एक पल के लिए मुझे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 949.55, "end": 951.66, "text": "फिर उसके होंठ का कोना ऊपर उठा,", "who": "", "voice": "narrator", "diary": false}, {"start": 951.66, "end": 954.68, "text": "और एक सेकंड के लिए, बस एक, गोलू वापस आ गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 955.13, "end": 955.88, "text": "प्रोफ़ेसर साहब।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 956.08, "end": 957.34, "text": "उसने मुझसे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 957.54, "end": 960.29, "text": "आपका वीडियो अब भी चैनल का सबसे पॉपुलर है।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 960.29, "end": 961.7, "text": "अननोन एंटिटी, फ़ीमेल?", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 961.7, "end": 963.72, "text": "उसी की कमाई से डीज़ल भरता हूँ।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 964.17, "end": 967.28, "text": "शाओनी इतनी ज़ोर से हँसी, कि रो पड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 967.28, "end": 970.56, "text": "क्षितिज ने गौरव को गले लगाया, छोटा सा,", "who": "", "voice": "narrator", "diary": false}, {"start": 970.56, "end": 973.67, "text": "अटपटा सा, और फिर तुरंत उसे लिख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 973.67, "end": 977.65, "text": "गब्बर ने अपना एक बड़ा हाथ गौरव के कंधे पर रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 977.65, "end": 979.21, "text": "और वहीं रहने दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 979.66, "end": 983.0, "text": "और चंपावत की पहाड़ियों पर सूरज उगा,", "who": "", "voice": "narrator", "diary": false}, {"start": 983.0, "end": 988.54, "text": "जहाँ इंसाफ़ का एक देवता कभी एक पत्थर से बदला गया बच्चा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 990.04, "end": 996.06, "text": "आठ बजे की मीटिंग, एक सादे सरकारी दफ़्तर में थी, एक थके हुए सीलिंग फ़ैन,", "who": "", "voice": "narrator", "diary": false}, {"start": 996.06, "end": 1000.9, "text": "और वर्दी में एक आदमी के साथ, जिसकी रैंक में कई सितारे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1000.9, "end": 1003.95, "text": "कमांडेंट धामी उनके बग़ल में बैठे थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 1003.95, "end": 1006.84, "text": "सीधी कमर, लगभग कुछ नहीं बोलते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1007.54, "end": 1009.78, "text": "हमने उन्हें सब कुछ दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1010.48, "end": 1015.3, "text": "मीटिंग से पहले के चार घंटे, मैंने वो एक काम करते हुए बिताए थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 1015.3, "end": 1019.04, "text": "जिसके लिए इस पूरी ट्रिप पर मैं सच में क़ाबिल था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1019.04, "end": 1024.96, "text": "गौरव के पास तीन हार्ड ड्राइव्स पर चौदह महीनों की फ़ुटेज थी: हज़ारों क्लिप्स,", "who": "", "voice": "narrator", "diary": false}, {"start": 1024.96, "end": 1029.86, "text": "वीड बाईस इक्यानवे फ़ाइनल फ़ाइनल डॉट एम-पी-फ़ोर जैसे नामों वाली।", "who": "", "voice": "narrator", "diary": false}, {"start": 1029.86, "end": 1034.77, "text": "हर क्लिप के मेटाडेटा में एक टाइमस्टैम्प और जी-पी-एस दबा हुआ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1034.77, "end": 1038.27, "text": "तो बसंती के पिछले हिस्से में, अपने लैपटॉप पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 1038.27, "end": 1041.62, "text": "मरती हुई बैटरी पर, मैंने एक स्क्रिप्ट लिखी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1041.62, "end": 1052.05, "text": "उसने हर फ़ाइल पढ़ी, वक़्त और जगह निकाली, उन्हें ट्रैकर लॉग से मिलाया, और पूरी चीज़ को एक मैप पर एक टाइमलाइन की तरह बिछा दिया: हर होटल,", "who": "", "voice": "narrator", "diary": false}, {"start": 1052.05, "end": 1054.46, "text": "ट्रेलहेड, कैंप, और पेट्रोल पंप,", "who": "", "voice": "narrator", "diary": false}, {"start": 1054.46, "end": 1057.97, "text": "जहाँ रोहन सहगल चौदह महीनों में गया था, और कब।", "who": "", "voice": "narrator", "diary": false}, {"start": 1058.42, "end": 1059.91, "text": "ये ग्लैमरस नहीं है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1059.91, "end": 1063.84, "text": "ये पाइथन की दो सौ लाइनें, और एक सी-एस-वी फ़ाइल है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1063.84, "end": 1071.78, "text": "लेकिन जब सितारों वाले आदमी ने मैप देखा, चौदह महीनों की एक लाल लाइन, पूरे उत्तराखंड के पार रेंगती हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 1071.78, "end": 1075.4, "text": "हर बिंदु क्लिक करने लायक़, हर बिंदु एक वीडियो,", "who": "", "voice": "narrator", "diary": false}, {"start": 1075.4, "end": 1080.35, "text": "तो उन्होंने मुझे एक तथाकथित प्रोफ़ेसर की तरह देखना बंद कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1080.8, "end": 1082.64, "text": "बाक़ी भी मेज़ पर गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1082.64, "end": 1084.92, "text": "रोहन की नोटबुक की फ़ोटोज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 1084.92, "end": 1090.44, "text": "छुपे हुए कैंप के, और रेडिएशन सिम्बल वाले केस के ड्रोन फ़्रेम्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 1090.44, "end": 1092.28, "text": "क्षितिज की नई नोटबुक,", "who": "", "voice": "narrator", "diary": false}, {"start": 1092.28, "end": 1096.66, "text": "और पुरानी वाली की जो कुछ उसे याद था, शब्द-दर-शब्द।", "who": "", "voice": "narrator", "diary": false}, {"start": 1096.66, "end": 1100.77, "text": "महेश के बारे में गब्बर का बयान, जिसने, पता चला,", "who": "", "voice": "narrator", "diary": false}, {"start": 1100.77, "end": 1106.11, "text": "रात दो बजे अपनी माँ के सामने पहले ही सब कुछ क़बूल कर लिया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1106.11, "end": 1109.97, "text": "और अब जोशीमठ के एक पुलिस स्टेशन में बैठा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1109.97, "end": 1111.81, "text": "गौरव का पूरा आर्काइव।", "who": "", "voice": "narrator", "diary": false}, {"start": 1111.81, "end": 1114.43, "text": "और एक वॉइस नोट, जिसमें हवा थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1114.88, "end": 1117.4, "text": "सितारों वाले आदमी देर तक देखते रहे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1117.4, "end": 1119.85, "text": "फिर उन्होंने एक घंटे तक सवाल पूछे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1119.85, "end": 1121.65, "text": "नोटबुक पहले किसके पास थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1121.65, "end": 1124.17, "text": "हम सीधे पुलिस के पास क्यों नहीं आए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1124.17, "end": 1126.69, "text": "क्या कोई स्क्रिप्ट ग़लत हो सकती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1126.69, "end": 1127.48, "text": "हो सकती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1127.48, "end": 1128.05, "text": "थी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1128.05, "end": 1129.71, "text": "उन्होंने मुझसे दिखवाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1129.71, "end": 1135.54, "text": "उन्होंने दो बार देहरादून फ़ोन किया, और दूसरी बार, किसी से बहस की, जो एक यूट्यूबर,", "who": "", "voice": "narrator", "diary": false}, {"start": 1135.54, "end": 1139.28, "text": "और पहले से न्यूज़ पर आ चुके एक प्रोफ़ेसर के कहने पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 1139.28, "end": 1143.38, "text": "एक इज़्ज़तदार कंपनी के मालिक की गिरफ़्तारी नहीं चाहता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1143.83, "end": 1146.13, "text": "फिर उन्होंने तीसरी बार अपना फ़ोन उठाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1146.58, "end": 1147.64, "text": "ग्यारह बजे तक,", "who": "", "voice": "narrator", "diary": false}, {"start": 1147.64, "end": 1151.72, "text": "तीन टूरिस्ट्स के लिए लुकआउट नोटिस वापस ले लिया गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1151.72, "end": 1155.8, "text": "साढ़े ग्यारह तक, एक टीम मुनस्यारी के लिए निकल चुकी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1155.8, "end": 1158.9, "text": "ग्यारह बजकर चालीस मिनट पर, मेरा फ़ोन बजा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1158.9, "end": 1163.74, "text": "जोशीमठ से, इंस्पेक्टर बिष्ट थे, और वो सच में शर्मिंदा लग रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1164.19, "end": 1164.41, "text": "सर।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 1164.41, "end": 1166.15, "text": "मैं सॉरी बोलना चाहता था।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 1166.15, "end": 1167.67, "text": "आप असली प्रोफ़ेसर हो।", "who": "इंस्पेक्टर बिष्ट", "voice": "bisht", "diary": false}, {"start": 1168.12, "end": 1169.06, "text": "इंस्पेक्टर साहब।", "who": "", "voice": "narrator", "diary": false}, {"start": 1169.26, "end": 1170.05, "text": "मैंने उनसे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1170.25, "end": 1172.57, "text": "मैं असली अननोन एंटिटी भी हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1172.57, "end": 1173.61, "text": "दोनों सच हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1175.11, "end": 1177.19, "text": "गौरव ने दोपहर को एक वीडियो अपलोड किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1177.64, "end": 1179.2, "text": "कोई रिंग लाइट नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1179.2, "end": 1181.92, "text": "कैपिटल लेटर्स में कोई टाइटल नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1181.92, "end": 1187.69, "text": "बस उसका चेहरा, उसका असली नाम, और उसके भाई के साथ जो हुआ, उसका एक छोटा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1187.69, "end": 1190.32, "text": "सीधा बयान, सबूत के कुछ फ़्रेम्स,", "who": "", "voice": "narrator", "diary": false}, {"start": 1190.32, "end": 1193.37, "text": "और आख़िर में पुलिस हेल्पलाइन का नंबर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1193.37, "end": 1197.49, "text": "घोस्टबस्टर गोलू के लगभग पचास लाख सब्सक्राइबर्स थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1197.49, "end": 1201.78, "text": "दोपहर दो बजे तक, उनमें से ज़्यादातर उसे देख चुके थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1202.23, "end": 1204.13, "text": "कमेंट्स की बाढ़ आ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1204.13, "end": 1204.58, "text": "सदमा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1204.58, "end": 1204.94, "text": "दुख।", "who": "", "voice": "narrator", "diary": false}, {"start": 1204.94, "end": 1206.57, "text": "द्रोणागिरी के लोग।", "who": "", "voice": "narrator", "diary": false}, {"start": 1206.57, "end": 1207.84, "text": "दिल्ली के लोग।", "who": "", "voice": "narrator", "diary": false}, {"start": 1207.84, "end": 1208.65, "text": "पोर्टर्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 1208.65, "end": 1209.47, "text": "ट्रेकर्स।", "who": "", "voice": "narrator", "diary": false}, {"start": 1209.47, "end": 1212.27, "text": "सैकड़ों लोग कहते हुए, हमें लगा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1212.27, "end": 1215.53, "text": "तुम एक मज़ाक़ हो, और हमें माफ़ करना।", "who": "", "voice": "narrator", "diary": false}, {"start": 1215.98, "end": 1221.24, "text": "और दोपहर दो बजकर सोलह मिनट पर, एक ऐसे अकाउंट से एक कमेंट,", "who": "", "voice": "narrator", "diary": false}, {"start": 1221.24, "end": 1224.47, "text": "जिसे हम में से कोई कभी नहीं भूलेगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1224.92, "end": 1227.99, "text": "एन-डी-पैंसठ: अच्छा किया, गौरव।", "who": "", "voice": "narrator", "diary": false}, {"start": 1227.99, "end": 1229.12, "text": "बहुत अच्छा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1229.12, "end": 1230.35, "text": "अब रेस शुरू।", "who": "", "voice": "narrator", "diary": false}, {"start": 1230.8, "end": 1234.64, "text": "गौरव ने अपना दूसरा फ़ोन उठाया, और जी-पी-एस वाले बिंदु को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1235.09, "end": 1237.26, "text": "वो अब रेंग नहीं रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1237.26, "end": 1238.58, "text": "वो चढ़ रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1238.58, "end": 1241.79, "text": "मुनस्यारी के ऊपर के मोड़ों पर ऊपर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1241.79, "end": 1243.97, "text": "ऊँचे बुग्यालों की तरफ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 1244.67, "end": 1245.7, "text": "खलिया की तरफ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 1246.4, "end": 1248.91, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1248.91, "end": 1251.17, "text": "डे थर्टीन, चंपावत।", "who": "", "voice": "narrator", "diary": true}, {"start": 1251.62, "end": 1253.72, "text": "गोलू, यानी गौरव रावत।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1253.72, "end": 1256.22, "text": "प्रताप सिंह रावत का पोता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1256.22, "end": 1258.72, "text": "कमला दादी की बहन का पोता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1258.72, "end": 1260.42, "text": "दीपक का छोटा भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1260.87, "end": 1263.15, "text": "दीपक: हाई-एल्टीट्यूड पोर्टर।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1263.15, "end": 1266.91, "text": "दो साल पहले आर. के प्राइवेट एक्सपीडिशन पर गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1266.91, "end": 1268.38, "text": "कभी वापस नहीं आया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1268.38, "end": 1269.6, "text": "कंपनी: क्रेवास।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1269.6, "end": 1271.16, "text": "परिवार को पैसे दिए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1271.61, "end": 1274.84, "text": "दीपक का आख़िरी वॉइस नोट: दादा का गीत सच है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1274.84, "end": 1277.32, "text": "सहगल साहब गरम पत्थर ढूँढ रहे हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1277.32, "end": 1281.31, "text": "उनके पास एक मशीन है, और ख़तरे के निशान वाला एक डब्बा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1281.31, "end": 1282.43, "text": "मैं मना करूँगा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1282.43, "end": 1284.24, "text": "मैं वापस आकर सब बताऊँगा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1284.24, "end": 1285.52, "text": "वो वापस नहीं आया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1285.97, "end": 1290.69, "text": "घोस्टबस्टर गोलू, एक मुखौटा, ताकि कोई उसे सीरियसली न ले,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1290.69, "end": 1293.69, "text": "ताकि वो कहीं भी आर. का पीछा कर सके।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1293.69, "end": 1294.63, "text": "चौदह महीने।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1294.63, "end": 1296.0, "text": "सवॉय में ट्रैकर।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1296.0, "end": 1300.72, "text": "मैंने उसके ख़िलाफ़ जो भी क्लू लिखा, वो उसके हक़ में था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1301.17, "end": 1303.0, "text": "नीली टोपी, दीपक की।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1303.0, "end": 1306.57, "text": "माउंटेनियरिंग इंस्टिट्यूट, उत्तरकाशी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1306.57, "end": 1310.23, "text": "पहाड़ पे अकेले मत जाना, वो आख़िरी बात,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1310.23, "end": 1312.74, "text": "जो गौरव ने दीपक से कही थी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1312.74, "end": 1314.28, "text": "चार सौ वीडियोज़।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1314.28, "end": 1316.02, "text": "वो हर बार कहता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1316.47, "end": 1319.23, "text": "भल्ला दीपक के एक्सपीडिशन पर था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1319.23, "end": 1320.3, "text": "एक ही थर्मस।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1320.3, "end": 1322.44, "text": "दीपक हर रात गीत गाता था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1322.44, "end": 1326.37, "text": "भल्ला बाँसुरी, गाना, सीटी, कुछ नहीं सह पाता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1326.37, "end": 1328.78, "text": "माफ़ कर दे, भाई, यानी दीपक।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1328.78, "end": 1331.72, "text": "भल्ला को पता है, ऊपर क्या हुआ था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1332.17, "end": 1334.66, "text": "पार्थ भाई ने एक स्क्रिप्ट लिखी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1334.66, "end": 1339.23, "text": "जिसने गौरव के चौदह महीनों के वीडियोज़ को एक मैप बना दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1339.23, "end": 1342.92, "text": "सितारों वाले आदमी ने तथाकथित कहना बंद कर दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1343.37, "end": 1349.07, "text": "चंपावत की बाघिन: गब्बर भैया के परदादा ने उसकी दुम देखी थी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1349.07, "end": 1353.39, "text": "जो कहानी के हर किलोमीटर पर एक मीटर बढ़ती है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1353.84, "end": 1354.83, "text": "नाम साफ़।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1354.83, "end": 1357.68, "text": "पुलिस मुनस्यारी जा रही है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1357.68, "end": 1361.74, "text": "आर. पहले से खलिया की तरफ़ चढ़ रहा है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1361.74, "end": 1363.06, "text": "अब रेस शुरू।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1363.51, "end": 1365.4, "text": "मैंने गौरव को गले लगाया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1365.4, "end": 1367.22, "text": "फिर मैंने उसे लिख लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1367.22, "end": 1368.24, "text": "दोनों सही थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 18.27, "bed": "police"}, {"at": 107.46, "bed": "roadnight"}, {"at": 120.61, "bed": "legend"}, {"at": 182.35, "bed": "caper"}, {"at": 227.76, "bed": "tender"}, {"at": 232.36, "bed": "lore"}, {"at": 290.94, "bed": "dawn"}, {"at": 335.34, "bed": "tender"}, {"at": 405.35, "bed": "legend"}, {"at": 465.31, "bed": "tender"}, {"at": 548.87, "bed": "cold"}, {"at": 613.87, "bed": "stillness"}, {"at": 623.9, "bed": "temple"}, {"at": 686.98, "bed": "discovery"}, {"at": 757.65, "bed": "suspicion"}, {"at": 833.78, "bed": "jagar"}, {"at": 860.81, "bed": "stillness"}, {"at": 869.61, "bed": "tender"}, {"at": 946.38, "bed": "golu"}, {"at": 962.97, "bed": "tender"}, {"at": 978.46, "bed": "dawn"}, {"at": 988.84, "bed": "code"}, {"at": 1079.6, "bed": "docu"}, {"at": 1145.38, "bed": "heroic"}, {"at": 1173.91, "bed": "tender"}, {"at": 1214.78, "bed": "threat"}, {"at": 1245.2, "bed": "diary"}, {"at": 1245.2, "bed": "diary"}], "hits": [{"at": 19.32, "fx": "phonering"}, {"at": 276.83, "fx": "page"}, {"at": 370.21, "fx": "sting"}, {"at": 402.54, "fx": "sting"}, {"at": 501.21, "fx": "sting_light"}, {"at": 574.68, "fx": "ping"}, {"at": 611.61, "fx": "sting"}, {"at": 620.19, "fx": "bell"}, {"at": 824.28, "fx": "sting"}, {"at": 861.86, "fx": "drumhit"}, {"at": 891.05, "fx": "sting_light"}, {"at": 1010.33, "fx": "typing"}, {"at": 1143.68, "fx": "sting_light"}, {"at": 1224.77, "fx": "ping"}, {"at": 1244.52, "fx": "sting"}, {"at": 1316.32, "fx": "sting_light"}, {"at": 1353.69, "fx": "sting"}], "next": {"label": "एपिसोड 14", "en": "Don't Answer If the Forest Calls Your Name", "hook": "रात तीन बजकर बारह मिनट। जंगल नाम पुकारता है। जवाब मत देना।"}};
